<script>
 import {onDestroy,tick} from 'svelte';import {isEditDoubleClick} from '../grid-click';import ProjectPeek from './ProjectPeek.svelte';
 import {Plus,FolderOpen,ArrowLeft,Check,Trash2,RotateCcw,Pencil,X,Minus,ZoomIn} from 'lucide-svelte';import {studio,current,assets,selectProject,select,toggle,run,updateProject,notify,trashSelected,importImages,clearSelection,liveAssets} from '../studio.svelte';import {api,bytes,stored,persist} from '../api';
 let name=$state(''),creating=$state(false),renaming=$state(false),query=$state(''),covers=$state({}),renameId=$state('');let filtered=$derived(assets().filter(a=>a.name.toLowerCase().includes(query.trim().toLowerCase())));let allVisibleSelected=$derived(filtered.length>0&&filtered.every(a=>studio.selected.includes(a.id)));
 let projectZoom=$state(stored('project-grid-zoom',1)),imageZoom=$state(stored('image-grid-zoom',1)),peek=$state(null),peekComponent=$state(),library;let openTimer;
 let zoom=$derived(studio.view==='projects'?projectZoom:imageZoom);
 function changeZoom(value){const next=Math.min(1.8,Math.max(.6,Math.round(value*100)/100));if(studio.view==='projects'){projectZoom=next;persist('project-grid-zoom',next);}else{imageZoom=next;persist('image-grid-zoom',next);}}
 function zoomWheel(e){if(!e.ctrlKey)return;e.preventDefault();e.stopPropagation();changeZoom(zoom*Math.exp(-e.deltaY*(e.deltaMode===1?20:1)*.0015));}
 function zoomArea(node){const handler=e=>zoomWheel(e);node.addEventListener('wheel',handler,{passive:false});return{destroy(){node.removeEventListener('wheel',handler);}};}
 function hidePeek(){clearTimeout(openTimer);peek=null;}
 function leavePeek(e){clearTimeout(openTimer);if(e?.type==='blur'&&!e.relatedTarget?.closest('.project-peek'))hidePeek();}
 function schedulePeek(project,anchor){clearTimeout(openTimer);if(peek?.project.id===project.id)return;openTimer=setTimeout(()=>peek={project,anchor},170);}
 async function cardWheel(e,project){if(e.ctrlKey)return; e.preventDefault();e.stopPropagation();clearTimeout(openTimer);if(peek?.project.id!==project.id)peek={project,anchor:e.currentTarget.closest('.project-card')};await tick();peekComponent?.scrollBy(e.deltaY*(e.deltaMode===1?20:1));}
 function openPreview(pid,id){hidePeek();selectProject(pid);select(id);}
 onDestroy(()=>{clearTimeout(openTimer);});
 let lastImageClick=null;
 function imageClick(e,id){
  const click={id,time:e.timeStamp,detail:e.detail,x:e.clientX,y:e.clientY};
  const edit=isEditDoubleClick(lastImageClick,click);
  lastImageClick=e.detail===1?click:null;
  toggle(id);
  if(edit)openAsset(id);
 }
 function openAsset(id){if(studio.trash)return;select(id);studio.view='canvas';}
 function back(){studio.trash=false;clearSelection();if(!liveAssets().some(a=>a.id===studio.aid))select(liveAssets()[0]?.id||'');studio.view='canvas';}
 function editName(project){creating=false;renaming=true;renameId=project.id;name=project.name;}
 function selectVisible(){const ids=filtered.map(a=>a.id);studio.selected=allVisibleSelected?studio.selected.filter(id=>!ids.includes(id)):[...new Set([...studio.selected,...ids])];studio.batchScope='auto';}
 async function create(){if(!name.trim())return;await run('Creating project',async()=>{const p=await api('project_create',{name:name.trim()});updateProject(p);selectProject(p.id);name='';creating=false;});}
 async function rename(){if(!name.trim())return;await run('Renaming',async()=>{updateProject(await api('project_rename',{projectId:renameId||studio.pid,name:name.trim()}));renaming=false;name='';});}
 async function restoreOne(id){studio.selected=[id];await trashSelected(true);}
</script>
<div bind:this={library} class="library" inert={!!studio.busy} use:zoomArea onscroll={hidePeek} style:--project-card-size={`${230*projectZoom}px`} style:--project-stack-height={`${180*projectZoom}px`} style:--image-card-size={`${170*imageZoom}px`} style:--image-thumb-height={`${165*imageZoom}px`}><div class="library-heading"><div><button class="text-button" onclick={back}><ArrowLeft size={14}/>Back to canvas</button><h1>{studio.view==='projects'?'Projects':studio.trash?'Trash':current()?.name}</h1></div><div class="button-row"><div class="grid-zoom" aria-label="Preview size"><button aria-label="Smaller previews" title="Smaller previews" disabled={zoom<=.6} onclick={()=>changeZoom(zoom-.1)}><Minus size={13}/></button><button class="zoom-readout" aria-label="Reset preview zoom" title="Ctrl + scroll · Reset to 100%" onclick={()=>changeZoom(1)}>{Math.round(zoom*100)}%</button><button aria-label="Larger previews" title="Larger previews" disabled={zoom>=1.8} onclick={()=>changeZoom(zoom+.1)}><ZoomIn size={13}/></button></div>{#if studio.view==='projects'}<button class="primary" onclick={()=>{creating=true;renaming=false;name='';}}><Plus size={15}/>New project</button>{:else}<button aria-label="Rename project" onclick={()=>editName(current())}><Pencil size={16}/></button><button class="line-button" onclick={()=>importImages(true)}><FolderOpen size={15}/>Folder</button><button class="primary" onclick={()=>importImages(false)}><Plus size={15}/>Import</button>{/if}</div></div>
{#if creating||renaming}<form class="name-form" onsubmit={e=>{e.preventDefault();creating?create():rename();}}><input aria-label="Project name" bind:value={name} placeholder="Project name" required maxlength="120"/><button class="primary" disabled={!name.trim()} type="submit">{creating?'Create':'Rename'}</button><button type="button" onclick={()=>{creating=false;renaming=false;}}>Cancel</button></form>{/if}
{#if studio.view==='projects'}<div class="project-grid">{#each studio.projects as project}<article class="project-card" onpointerenter={e=>{if(e.pointerType!=='touch')schedulePeek(project,e.currentTarget);}} onpointerleave={leavePeek}><button class="project-open" onfocus={e=>schedulePeek(project,e.currentTarget.closest('.project-card'))} onblur={leavePeek} oncontextmenu={e=>{e.preventDefault();editName(project);}} onwheel={e=>cardWheel(e,project)} onclick={()=>{hidePeek();selectProject(project.id);}}><div class="project-stack">{#each [...project.assets.filter(a=>!a.trashed),...project.assets.filter(a=>!a.trashed)].slice(covers[project.id]||0,(covers[project.id]||0)+Math.min(3,project.assets.filter(a=>!a.trashed).length)).reverse() as a,i}<img src={studio.thumbs[a.id]} alt="" style:transform={`rotate(${(i-1)*7}deg) translateX(${(i-1)*9}px)`}/>{/each}{#if !project.assets.some(a=>!a.trashed)}<FolderOpen size={36}/>{/if}</div><div><h2>{project.name}</h2><span>{project.assets.filter(a=>!a.trashed).length} images</span></div></button><button class="project-rename" aria-label={`Rename ${project.name}`} title="Rename project" onclick={()=>editName(project)}><Pencil size={15}/></button></article>{/each}</div>
{:else}<div class="library-toolbar"><div class="segmented"><button class:active={!studio.trash} onclick={()=>{studio.trash=false;clearSelection();query='';}}>Images</button><button class:active={studio.trash} onclick={()=>{studio.trash=true;clearSelection();query='';}}>Trash</button></div><input class="search" aria-label="Search images" bind:value={query} placeholder="Search images"/><button class="text-button" disabled={!filtered.length} onclick={selectVisible}>{allVisibleSelected?'Deselect visible':query.trim()?'Select results':'Select all'}</button>{#if studio.selected.length}<button class="line-button" onclick={()=>trashSelected(studio.trash)}>{#if studio.trash}<RotateCcw size={14}/>Restore {studio.selected.length}{:else}<Trash2 size={14}/>Trash {studio.selected.length}{/if}</button><button aria-label="Clear selection" onclick={clearSelection}><X size={14}/></button>{/if}</div><div class="image-grid">{#each filtered as a}<article class:selected={studio.selected.includes(a.id)}><button class="image-open" onclick={e=>imageClick(e,a.id)} onkeydown={e=>{if(e.key==='Enter'){e.preventDefault();openAsset(a.id);}}} aria-label={`Select ${a.name}`} aria-pressed={studio.selected.includes(a.id)} title={studio.trash?'Click to select':'Click to select · Double-click to edit'}><img src={studio.thumbs[a.id]} alt={a.name} loading="lazy"/></button><button class="image-check" aria-label={`Select ${a.name}`} aria-pressed={studio.selected.includes(a.id)} onclick={()=>toggle(a.id)}>{#if studio.selected.includes(a.id)}<Check size={12}/>{/if}</button><div><b>{a.name}</b><small>{a.width} × {a.height}<span>{bytes(a.bytes)}</span></small>{#if studio.trash}<button class="text-button" onclick={()=>restoreOne(a.id)}><RotateCcw size={13}/>Restore</button>{/if}</div></article>{/each}</div>{#if !filtered.length}<div class="empty"><FolderOpen size={36}/><h2>{query.trim()?'No matching images':studio.trash?'Trash is empty':'No images yet'}</h2>{#if query.trim()}<button class="line-button" onclick={()=>query=''}>Clear search</button>{:else if !studio.trash}<button class="primary" onclick={()=>importImages(false)}>Import images</button>{/if}</div>{/if}{/if}</div>
{#if peek&&studio.view==='projects'}<ProjectPeek bind:this={peekComponent} project={peek.project} thumbs={studio.thumbs} anchor={peek.anchor} onselect={openPreview} onclose={hidePeek} onzoom={zoomWheel}/>{/if}
